def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {value: rank for rank, value in enumerate(sorted(set(a)), 1)}
    size = len(ranks)
    tree = [0] * (size + 1)
    result = []

    for i, height in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank <= size:
                tree[rank] -= 1
                rank += rank & -rank

        rank = ranks[height]
        count_not_taller = 0
        while rank:
            count_not_taller += tree[rank]
            rank -= rank & -rank

        result.append(min(i, k) - count_not_taller)

        rank = ranks[height]
        while rank <= size:
            tree[rank] += 1
            rank += rank & -rank

    return result
